@staticmethod
def prepare_current_slot_for_template(
    current_step: Optional[FlowStep],
) -> Tuple[Optional[str], Optional[str]]:
    """Prepare the current slot for the template.

    Args:
        current_step: The current step in the flow.

    Returns:
        The name and description of the slot being collected.
    """
    if isinstance(current_step, CollectInformationFlowStep):
        return current_step.collect, current_step.description
    return None, None
